//! The evidence records of G2 group A3 (ADOPTED by the owner, 2026-11-09,
//! B3): `EquivocationEvidenceV1` and `UpgradeConflictEvidenceV1`.
//!
//! The known-answer tests reproduce the byte-review draft's evidence vectors
//! (`docs/proposals/g2-byte-review/vectors.json`, generated by the
//! stdlib-only reference `generate.py`, not by this crate) byte for byte. The
//! vote vectors (`tests/vectors/finality_vote_v1.json`) supply a second valid
//! signature over one body and a nil precommit. Both required CI jobs (x86_64
//! and aarch64) run these tests, so the same fixed bytes are checked on both
//! architectures. Every key is a test-only key from a seed `[i; 32]`.
//!
//! The manifest (A4, B4) is not adopted: the upgrade-conflict tests verify
//! manifests with a lookup table of the draft's manifests and digests, never
//! with an implementation of A4.

use ed25519_dalek::{Signer, SigningKey};
use serde_json::Value;
use sumchain_finality_foundations::encoding::{DecodeError, Round, MAX_ROUND};
use sumchain_finality_foundations::evidence::{
    decode_and_verify_evidence, decode_and_verify_upgrade_conflict, manifest_len,
    upgrade_conflict_len, verify_evidence, verify_upgrade_conflict, EquivocationEvidenceV1,
    EvidenceDecodeError, EvidencePairError, EvidenceVerifyError, ManifestIdentity, ManifestRefusal,
    ManifestVerifier, Member, UpgradeConflictDecodeError, UpgradeConflictError,
    UpgradeConflictEvidenceV1, UpgradeConflictVerifyError, EVIDENCE_LEN, EVIDENCE_MAGIC,
    EVIDENCE_SCHEMA, MANIFEST_FIXED_LEN, MANIFEST_SIGNER_COUNT_OFFSET, UPGRADE_CONFLICT_FRAME_LEN,
    UPGRADE_CONFLICT_MAGIC, UPGRADE_CONFLICT_SCHEMA,
};
use sumchain_finality_foundations::vote::{
    AuthenticatedValidatorSet, FinalityVoteV1, SignedFinalityVoteV1, TallyOutcome, VoteContext,
    VoteDecodeError, VoteTally, VoteType, VoteVerifyError, NIL_BLOCK_ID,
};
use sumchain_finality_foundations::Digest;

const DRAFT_VECTORS: &str = include_str!("../../../docs/proposals/g2-byte-review/vectors.json");
const VOTE_VECTORS: &str = include_str!("vectors/finality_vote_v1.json");

fn draft_doc() -> Value {
    serde_json::from_str(DRAFT_VECTORS).expect("the draft vectors are JSON")
}

fn draft(name: &str) -> Vec<u8> {
    let v = draft_doc();
    let hex = v["vectors"]
        .as_array()
        .expect("a vector list")
        .iter()
        .find(|x| x["name"] == name)
        .unwrap_or_else(|| panic!("draft vector {name:?}"))["hex"]
        .as_str()
        .expect("a hex string")
        .to_owned();
    hex::decode(hex).expect("valid hex")
}

/// A draft magic as bytes: the JSON spells the NUL as `\0`.
fn draft_magic(name: &str) -> Vec<u8> {
    draft_doc()["magics"][name]
        .as_str()
        .expect("a magic")
        .replace("\\0", "\0")
        .into_bytes()
}

fn vote_wire(section: &str, name: &str) -> SignedFinalityVoteV1 {
    let v: Value = serde_json::from_str(VOTE_VECTORS).expect("the vote vectors are JSON");
    let entry = v[section]
        .as_array()
        .unwrap()
        .iter()
        .find(|e| e["name"] == name)
        .unwrap_or_else(|| panic!("no {section} vote vector {name:?}"));
    let wire = hex::decode(entry["wire"].as_str().unwrap()).unwrap();
    SignedFinalityVoteV1::from_wire(&wire).expect("a valid vote vector")
}

fn digest(bytes: &[u8]) -> Digest {
    bytes.try_into().expect("32 bytes")
}

fn seed_key(index: u16) -> SigningKey {
    SigningKey::from_bytes(&[u8::try_from(index + 1).expect("small test set"); 32])
}

const HEIGHT: u64 = 7;

/// The draft's context: n = 4 seed keys, the synthetic config commitment.
struct Ctx {
    commitment: Digest,
    set: AuthenticatedValidatorSet,
}

impl VoteContext for Ctx {
    fn consensus_config_commitment(&self, height: u64) -> Option<Digest> {
        (height == HEIGHT).then_some(self.commitment)
    }
    fn validator_set(&self, height: u64) -> Option<&AuthenticatedValidatorSet> {
        (height == HEIGHT).then_some(&self.set)
    }
}

fn ctx() -> Ctx {
    let keys: Vec<[u8; 32]> = (0..4)
        .map(|i| seed_key(i).verifying_key().to_bytes())
        .collect();
    let set = AuthenticatedValidatorSet::from_keys(&keys).expect("the seed set is valid");
    assert_eq!(
        set.commitment().as_slice(),
        draft("valset n=4 commitment").as_slice(),
        "the seed set is the draft's n = 4 set"
    );
    Ctx {
        commitment: digest(&draft("synthetic config commitment")),
        set,
    }
}

fn precommit(index: u16, block_id: Digest) -> FinalityVoteV1 {
    let c = ctx();
    FinalityVoteV1 {
        consensus_config_commitment: c.commitment,
        height: HEIGHT,
        block_id,
        round: Round::ZERO,
        vote_type: VoteType::Precommit,
        validator_set_commitment: *c.set.commitment(),
        validator_index: index,
    }
}

/// Sign `vote` with the seed key of `signer`.
fn sign(vote: FinalityVoteV1, signer: u16) -> SignedFinalityVoteV1 {
    SignedFinalityVoteV1 {
        vote,
        signature: seed_key(signer).sign(&vote.preimage()).to_bytes(),
    }
}

/// The record's bytes for two votes in the order given, with none of the
/// pair rules applied.
fn raw(a: &SignedFinalityVoteV1, b: &SignedFinalityVoteV1) -> Vec<u8> {
    let mut out = EVIDENCE_MAGIC.to_vec();
    out.extend_from_slice(&EVIDENCE_SCHEMA.to_le_bytes());
    for v in [a, b] {
        out.extend_from_slice(&v.vote.body());
        out.extend_from_slice(&v.signature);
    }
    out
}

fn draft_evidence() -> Vec<u8> {
    draft("equivocation evidence idx=2 h=7 r=0 precommit")
}

/// The two votes of the draft record, signed here by validator 2's seed key.
fn draft_votes() -> (SignedFinalityVoteV1, SignedFinalityVoteV1) {
    let want = draft_evidence();
    let block_a = digest(&want[9 + 42..9 + 74]);
    let block_b = digest(&want[186 + 42..186 + 74]);
    (
        sign(precommit(2, block_a), 2),
        sign(precommit(2, block_b), 2),
    )
}

fn decode_err(bytes: &[u8]) -> EvidenceDecodeError {
    EquivocationEvidenceV1::decode(bytes).expect_err("refused")
}

