#[test]
fn constants_match_the_adopted_format() {
    assert_eq!(EVIDENCE_MAGIC.as_slice(), draft_magic("M_EVID").as_slice());
    assert_eq!(
        UPGRADE_CONFLICT_MAGIC.as_slice(),
        draft_magic("M_UCONFLICT").as_slice()
    );
    assert_eq!((EVIDENCE_SCHEMA, UPGRADE_CONFLICT_SCHEMA), (1, 1));
    assert_eq!(EVIDENCE_LEN, 363);
    assert_eq!(UPGRADE_CONFLICT_FRAME_LEN, 17);
    assert_eq!(
        (MANIFEST_FIXED_LEN, MANIFEST_SIGNER_COUNT_OFFSET),
        (278, 276)
    );
    assert_eq!(manifest_len(2), 410);
    // 573 + 66·(k_a + k_b): 837 at n = 2; 969 to 1,101 at n = 4.
    assert_eq!(upgrade_conflict_len(2, 2), 837);
    assert_eq!(upgrade_conflict_len(3, 3), 969);
    assert_eq!(upgrade_conflict_len(4, 4), 1_101);
    for (k_a, k_b) in [(0u16, 0u16), (1, 7), (43_691, 65_535), (65_535, 65_535)] {
        assert_eq!(
            upgrade_conflict_len(k_a, k_b),
            573 + 66 * (usize::from(k_a) + usize::from(k_b))
        );
    }
}

