#[test]
fn kat_reproduces_the_draft_equivocation_evidence() {
    let want = draft_evidence();
    let (a, b) = draft_votes();
    assert!(a.vote.block_id < b.vote.block_id);
    // Given in either order, the record is the draft's, byte for byte.
    for (x, y) in [(a, b), (b, a)] {
        let built = EquivocationEvidenceV1::new(x, y).unwrap();
        assert_eq!(
            hex::encode(built.encode()),
            hex::encode(&want),
            "byte for byte"
        );
    }
    let decoded = EquivocationEvidenceV1::decode(&want).unwrap();
    assert_eq!(decoded, EquivocationEvidenceV1::new(a, b).unwrap());
    assert_eq!((*decoded.first(), *decoded.second()), (a, b));
    assert_eq!(decoded.encode().as_slice(), want.as_slice());
    let verified = decode_and_verify_evidence(&want, &ctx()).unwrap();
    assert_eq!(verified.evidence(), &decoded);
    // The bodies are the ratified vote bodies (validator 2, h = 7, r = 0,
    // precommit), each signed over D_VOTE ‖ body.
    assert_eq!(&want[9..122], a.vote.body().as_slice());
    assert_eq!(&want[186..299], b.vote.body().as_slice());
}

// ---------------------------------------------------------------------------
// EquivocationEvidenceV1: refused
// ---------------------------------------------------------------------------

#[test]
fn every_length_but_363_is_refused() {
    let want = draft_evidence();
    for len in 0..EVIDENCE_LEN {
        assert_eq!(
            decode_err(&want[..len]),
            EvidenceDecodeError::Length { actual: len }
        );
    }
    for extra in [1usize, 2, 64, 363] {
        let mut long = want.clone();
        long.resize(EVIDENCE_LEN + extra, 0);
        assert_eq!(
            decode_err(&long),
            EvidenceDecodeError::Length {
                actual: EVIDENCE_LEN + extra
            },
            "{extra} trailing bytes"
        );
    }
}

#[test]
fn the_magic_and_schema_are_exact() {
    let want = draft_evidence();
    for i in 0..EVIDENCE_MAGIC.len() {
        for bit in 0..8 {
            let mut bad = want.clone();
            bad[i] ^= 1 << bit;
            assert_eq!(decode_err(&bad), EvidenceDecodeError::Magic, "byte {i}");
        }
    }
    let mut certificate_magic = want.clone();
    certificate_magic[..7].copy_from_slice(&draft_magic("M_CERT"));
    assert_eq!(decode_err(&certificate_magic), EvidenceDecodeError::Magic);
    for schema in [0u16, 2, 0x0100, u16::MAX] {
        let mut bad = want.clone();
        bad[7..9].copy_from_slice(&schema.to_le_bytes());
        assert_eq!(decode_err(&bad), EvidenceDecodeError::Schema(schema));
    }
}

#[test]
fn a_body_the_vote_decoder_refuses_is_refused() {
    let want = draft_evidence();
    for (member, start) in [(Member::First, 9usize), (Member::Second, 186)] {
        let at = |offset: usize, bytes: &[u8]| {
            let mut bad = want.clone();
            bad[start + offset..start + offset + bytes.len()].copy_from_slice(bytes);
            decode_err(&bad)
        };
        for code in [0u8, 3, 0xff] {
            assert_eq!(
                at(78, &[code]),
                EvidenceDecodeError::Vote {
                    member,
                    error: VoteDecodeError::VoteType(code)
                }
            );
        }
        assert!(matches!(
            at(74, &(MAX_ROUND + 1).to_le_bytes()),
            EvidenceDecodeError::Vote {
                member: m,
                error: VoteDecodeError::Round(_)
            } if m == member
        ));
        assert_eq!(
            at(32, &2u16.to_le_bytes()),
            EvidenceDecodeError::Vote {
                member,
                error: VoteDecodeError::Schema(2)
            }
        );
    }
}

#[test]
fn votes_for_different_slots_are_refused() {
    let (a, b) = draft_votes();
    let other_round = Round::new(1).unwrap();
    let changes: [(&str, FinalityVoteV1); 6] = [
        (
            "commitment",
            FinalityVoteV1 {
                consensus_config_commitment: [0xc1; 32],
                ..b.vote
            },
        ),
        (
            "height",
            FinalityVoteV1 {
                height: HEIGHT + 1,
                ..b.vote
            },
        ),
        (
            "round",
            FinalityVoteV1 {
                round: other_round,
                ..b.vote
            },
        ),
        (
            "type",
            FinalityVoteV1 {
                vote_type: VoteType::Prevote,
                ..b.vote
            },
        ),
        (
            "validator-set commitment",
            FinalityVoteV1 {
                validator_set_commitment: [0x5b; 32],
                ..b.vote
            },
        ),
        (
            "index",
            FinalityVoteV1 {
                validator_index: 3,
                ..b.vote
            },
        ),
    ];
    for (field, vote) in changes {
        let other = sign(vote, 2);
        assert_eq!(
            EquivocationEvidenceV1::new(a, other),
            Err(EvidencePairError::DifferentSlots),
            "{field}"
        );
        assert_eq!(
            decode_err(&raw(&a, &other)),
            EvidenceDecodeError::Pair(EvidencePairError::DifferentSlots),
            "{field}"
        );
    }
}

#[test]
fn identical_blocks_and_the_reverse_order_are_refused() {
    let (a, b) = draft_votes();
    // One record per pair: B before A is refused, never re-sorted.
    assert_eq!(
        decode_err(&raw(&b, &a)),
        EvidenceDecodeError::Pair(EvidencePairError::NonCanonicalOrder)
    );
    // One vote twice.
    assert_eq!(
        EquivocationEvidenceV1::new(a, a),
        Err(EvidencePairError::IdenticalBlocks)
    );
    assert_eq!(
        decode_err(&raw(&a, &a)),
        EvidenceDecodeError::Pair(EvidencePairError::IdenticalBlocks)
    );
    // Nil twice is one block too.
    let nil = sign(precommit(2, NIL_BLOCK_ID), 2);
    assert_eq!(
        EquivocationEvidenceV1::new(nil, nil),
        Err(EvidencePairError::IdenticalBlocks)
    );
}

#[test]
fn every_single_byte_flip_of_the_draft_record_is_refused() {
    let want = draft_evidence();
    let ctx = ctx();
    assert!(decode_and_verify_evidence(&want, &ctx).is_ok());
    let mut unrefused = Vec::new();
    for i in 0..want.len() {
        let mut bad = want.clone();
        bad[i] ^= 0x01;
        if decode_and_verify_evidence(&bad, &ctx).is_ok() {
            unrefused.push(i);
        }
    }
    assert!(unrefused.is_empty(), "unrefused offsets {unrefused:?}");
}

#[test]
fn verification_names_the_vote_it_refuses() {
    let (a, b) = draft_votes();
    let ctx = ctx();
    let err = |x: SignedFinalityVoteV1, y: SignedFinalityVoteV1| {
        let evidence = EquivocationEvidenceV1::new(x, y).unwrap();
        verify_evidence(&evidence, &ctx).expect_err("refused")
    };
    let mut bad_a = a;
    bad_a.signature[0] ^= 0x01;
    assert_eq!(
        err(bad_a, b),
        EvidenceVerifyError {
            member: Member::First,
            error: VoteVerifyError::Signature
        }
    );
    let mut bad_b = b;
    bad_b.signature[63] ^= 0x80;
    assert_eq!(
        err(a, bad_b),
        EvidenceVerifyError {
            member: Member::Second,
            error: VoteVerifyError::Signature
        }
    );
    // Signed by another validator's key.
    assert_eq!(
        err(a, sign(b.vote, 1)),
        EvidenceVerifyError {
            member: Member::Second,
            error: VoteVerifyError::Signature
        }
    );
    // An index outside the authenticated set (n = 4).
    let (x, y) = (
        sign(precommit(4, a.vote.block_id), 4),
        sign(precommit(4, b.vote.block_id), 4),
    );
    assert_eq!(
        err(x, y),
        EvidenceVerifyError {
            member: Member::First,
            error: VoteVerifyError::IndexOutOfRange { index: 4, n: 4 }
        }
    );
    // Another node's commitment: the context decides, never the record.
    let other = Ctx {
        commitment: [0xc1; 32],
        set: ctx.set.clone(),
    };
    let evidence = EquivocationEvidenceV1::new(a, b).unwrap();
    assert_eq!(
        verify_evidence(&evidence, &other),
        Err(EvidenceVerifyError {
            member: Member::First,
            error: VoteVerifyError::ConfigCommitmentMismatch
        })
    );
}

// ---------------------------------------------------------------------------
// EquivocationEvidenceV1: what counts (VOTE V-3, V-4)
// ---------------------------------------------------------------------------

fn counted_then(first: SignedFinalityVoteV1, then: SignedFinalityVoteV1) -> TallyOutcome {
    let ctx = ctx();
    let mut tally = VoteTally::new(&ctx.set);
    let verified = |v| sumchain_finality_foundations::vote::verify(&v, &ctx).unwrap();
    assert_eq!(tally.insert(&verified(first)), Ok(TallyOutcome::Counted));
    tally.insert(&verified(then)).unwrap()
}

#[test]
fn nil_against_non_nil_is_a_conflict() {
    let block = vote_wire("golden", "precommit h=7 r=0 validator 1");
    let nil = vote_wire("valid", "precommit h=7 r=0 validator 1 nil");
    assert!(nil.vote.is_nil() && !block.vote.is_nil());
    let ctx = ctx();
    assert_eq!(block.vote.consensus_config_commitment, ctx.commitment);
    assert_eq!(&block.vote.validator_set_commitment, ctx.set.commitment());

    let mut records = Vec::new();
    for (x, y) in [(block, nil), (nil, block)] {
        let TallyOutcome::Equivocation(e) = counted_then(x, y) else {
            panic!("nil against non-nil is equivocation");
        };
        let evidence = EquivocationEvidenceV1::from_equivocation(&e).unwrap();
        assert_eq!(*evidence.first(), nil, "the nil vote sorts first");
        assert_eq!(*evidence.second(), block);
        let bytes = evidence.encode();
        assert_eq!(
            decode_and_verify_evidence(&bytes, &ctx).unwrap().evidence(),
            &evidence
        );
        records.push(bytes);
    }
    assert_eq!(records[0], records[1], "one record whichever came first");
}

#[test]
fn an_identical_body_with_another_signature_is_a_duplicate_not_evidence() {
    let x = vote_wire("golden", "precommit h=7 r=0 validator 1");
    let alt = vote_wire(
        "valid",
        "precommit h=7 r=0 validator 1 alternative signature",
    );
    assert_eq!(x.vote, alt.vote);
    assert_ne!(x.signature, alt.signature);
    let ctx = ctx();
    for v in [x, alt] {
        assert!(sumchain_finality_foundations::vote::verify(&v, &ctx).is_ok());
    }
    assert_eq!(counted_then(x, alt), TallyOutcome::Duplicate);
    assert_eq!(
        EquivocationEvidenceV1::new(x, alt),
        Err(EvidencePairError::IdenticalBlocks)
    );
    for (p, q) in [(&x, &alt), (&alt, &x)] {
        assert_eq!(
            decode_err(&raw(p, q)),
            EvidenceDecodeError::Pair(EvidencePairError::IdenticalBlocks)
        );
    }
}

#[test]
fn a_tally_equivocation_gives_one_record_whichever_vote_came_first() {
    let x = vote_wire("golden", "precommit h=7 r=0 validator 1");
    let y = vote_wire("valid", "precommit h=7 r=0 validator 1 conflicting block");
    let ctx = ctx();
    let record = |first, then| match counted_then(first, then) {
        TallyOutcome::Equivocation(e) => EquivocationEvidenceV1::from_equivocation(&e)
            .unwrap()
            .encode(),
        other => panic!("expected equivocation, got {other:?}"),
    };
    let one = record(x, y);
    assert_eq!(one, record(y, x));
    assert!(decode_and_verify_evidence(&one, &ctx).is_ok());
}

// ---------------------------------------------------------------------------
// UpgradeConflictEvidenceV1
// ---------------------------------------------------------------------------

/// A stand-in for the A4 verifier, which is not adopted: it accepts exactly
/// the manifests in its table, with the identity the draft gives them.
struct Table(Vec<(Vec<u8>, ManifestIdentity)>);

impl ManifestVerifier for Table {
    fn verify(&self, manifest: &[u8]) -> Result<ManifestIdentity, ManifestRefusal> {
        self.0
            .iter()
            .find(|(bytes, _)| bytes.as_slice() == manifest)
            .map(|(_, identity)| *identity)
            .ok_or_else(|| ManifestRefusal("not a manifest in the table".into()))
    }
}

fn manifest_a() -> Vec<u8> {
    draft("manifest A n=2 both signers")
}

fn manifest_b() -> Vec<u8> {
    draft("manifest B n=2 both signers")
}

fn identity(sequence: u64, digest_vector: &str) -> ManifestIdentity {
    ManifestIdentity {
        sequence,
        digest: digest(&draft(digest_vector)),
    }
}

fn draft_table() -> Table {
    Table(vec![
        (manifest_a(), identity(1, "manifest A digest")),
        (manifest_b(), identity(1, "manifest B digest")),
    ])
}

fn draft_conflict() -> Vec<u8> {
    draft("upgrade-conflict evidence A/B sequence 1")
}

/// The record's bytes for two manifests in the order given, with the length
/// fields taken from the manifests.
fn frame(a: &[u8], b: &[u8]) -> Vec<u8> {
    let mut out = UPGRADE_CONFLICT_MAGIC.to_vec();
    out.extend_from_slice(&UPGRADE_CONFLICT_SCHEMA.to_le_bytes());
    for m in [a, b] {
        out.extend_from_slice(&u32::try_from(m.len()).unwrap().to_le_bytes());
        out.extend_from_slice(m);
    }
    out
}

/// An opaque manifest-shaped value: 276 filler bytes, the signer count `k`
/// and `k` filler entries. Only the framing reads it.
fn shaped(k: u16, fill: u8) -> Vec<u8> {
    let mut m = vec![fill; MANIFEST_SIGNER_COUNT_OFFSET];
    m.extend_from_slice(&k.to_le_bytes());
    m.resize(manifest_len(k), fill);
    m
}

fn conflict_decode_err(bytes: &[u8]) -> UpgradeConflictDecodeError {
    UpgradeConflictEvidenceV1::decode(bytes).expect_err("refused")
}

#[test]
fn kat_reproduces_the_draft_upgrade_conflict_evidence() {
    let want = draft_conflict();
    assert_eq!(want.len(), upgrade_conflict_len(2, 2));
    let (a, b) = (manifest_a(), manifest_b());
    for m in [&a, &b] {
        assert_eq!(m.len(), manifest_len(2));
        assert_eq!(
            &m[MANIFEST_SIGNER_COUNT_OFFSET..MANIFEST_FIXED_LEN],
            &[2, 0]
        );
    }
    let decoded = UpgradeConflictEvidenceV1::decode(&want).unwrap();
    assert_eq!(
        (decoded.first(), decoded.second()),
        (a.as_slice(), b.as_slice())
    );
    assert_eq!(hex::encode(decoded.encode()), hex::encode(&want));

    let table = draft_table();
    let verified = verify_upgrade_conflict(&decoded, &table).unwrap();
    assert_eq!(verified.sequence(), 1);
    assert_eq!(
        verified.digests(),
        &[
            digest(&draft("manifest A digest")),
            digest(&draft("manifest B digest"))
        ]
    );
    assert_eq!(
        decode_and_verify_upgrade_conflict(&want, &table).unwrap(),
        verified
    );
    // Built from the manifests in either order: the draft's bytes.
    for (x, y) in [(&a, &b), (&b, &a)] {
        let built = UpgradeConflictEvidenceV1::from_manifests(x, y, &table).unwrap();
        assert_eq!(built, verified);
        assert_eq!(built.evidence().encode(), want);
    }
}

#[test]
fn upgrade_conflict_sizes_follow_the_signer_counts() {
    for (k_a, k_b) in [(0u16, 0u16), (2, 2), (3, 3), (3, 4), (4, 4)] {
        let bytes = frame(&shaped(k_a, 0xa1), &shaped(k_b, 0xb2));
        assert_eq!(bytes.len(), upgrade_conflict_len(k_a, k_b));
        let decoded = UpgradeConflictEvidenceV1::decode(&bytes).unwrap();
        assert_eq!(decoded.encode(), bytes);
    }
}

#[test]
fn upgrade_conflict_framing_is_strict() {
    let want = draft_conflict();
    // Every truncation, and a trailing byte.
    for len in 0..want.len() {
        assert!(
            UpgradeConflictEvidenceV1::decode(&want[..len]).is_err(),
            "{len} bytes"
        );
    }
    let mut long = want.clone();
    long.push(0);
    assert_eq!(
        conflict_decode_err(&long),
        UpgradeConflictDecodeError::Framing(DecodeError::Trailing(1))
    );
    // Magic and schema.
    for i in 0..UPGRADE_CONFLICT_MAGIC.len() {
        let mut bad = want.clone();
        bad[i] ^= 0x01;
        assert_eq!(conflict_decode_err(&bad), UpgradeConflictDecodeError::Magic);
    }
    let mut evidence_magic = want.clone();
    evidence_magic[..7].copy_from_slice(&EVIDENCE_MAGIC);
    assert_eq!(
        conflict_decode_err(&evidence_magic),
        UpgradeConflictDecodeError::Magic
    );
    for schema in [0u16, 2, u16::MAX] {
        let mut bad = want.clone();
        bad[7..9].copy_from_slice(&schema.to_le_bytes());
        assert_eq!(
            conflict_decode_err(&bad),
            UpgradeConflictDecodeError::Schema(schema)
        );
    }
    // A length field that disagrees with its manifest.
    let (a, b) = (manifest_a(), manifest_b());
    let len_a_at = 9..13;
    let len_b_at = 13 + a.len()..17 + a.len();
    for delta in [-66i64, -1, 1, 66] {
        let mut bad = want.clone();
        let len = (a.len() as i64 + delta) as u32;
        bad[len_a_at.clone()].copy_from_slice(&len.to_le_bytes());
        assert!(
            UpgradeConflictEvidenceV1::decode(&bad).is_err(),
            "len_a {delta:+}"
        );
        let mut bad = want.clone();
        let len = (b.len() as i64 + delta) as u32;
        bad[len_b_at.clone()].copy_from_slice(&len.to_le_bytes());
        assert!(
            UpgradeConflictEvidenceV1::decode(&bad).is_err(),
            "len_b {delta:+}"
        );
    }
    // A length past the input is refused before anything is copied.
    let mut huge = want.clone();
    huge[len_a_at].copy_from_slice(&u32::MAX.to_le_bytes());
    assert!(matches!(
        conflict_decode_err(&huge),
        UpgradeConflictDecodeError::Framing(DecodeError::Truncated { .. })
    ));
    // A manifest whose own signer count disagrees with its length.
    for (member, at) in [
        (Member::First, 13 + MANIFEST_SIGNER_COUNT_OFFSET),
        (Member::Second, 17 + a.len() + MANIFEST_SIGNER_COUNT_OFFSET),
    ] {
        for k in [0u16, 1, 3, u16::MAX] {
            let mut bad = want.clone();
            bad[at..at + 2].copy_from_slice(&k.to_le_bytes());
            assert_eq!(
                conflict_decode_err(&bad),
                UpgradeConflictDecodeError::ManifestLength {
                    member,
                    actual: manifest_len(2)
                },
                "k = {k}"
            );
        }
    }
    // A manifest shorter than its fixed part.
    for short in [0usize, 1, 277] {
        let bytes = frame(&vec![0u8; short], &b);
        assert_eq!(
            conflict_decode_err(&bytes),
            UpgradeConflictDecodeError::ManifestLength {
                member: Member::First,
                actual: short
            }
        );
    }
}

#[test]
fn upgrade_conflict_validity_comes_from_the_injected_verifier() {
    let (a, b) = (manifest_a(), manifest_b());
    let table = draft_table();
    let verify_err =
        |bytes: &[u8], verifier: &dyn ManifestVerifier| match decode_and_verify_upgrade_conflict(
            bytes, verifier,
        ) {
            Err(UpgradeConflictError::Verify(e)) => e,
            other => panic!("expected a verification refusal, got {other:?}"),
        };
    // B before A decodes, and is refused: one record per pair.
    assert_eq!(
        verify_err(&frame(&b, &a), &table),
        UpgradeConflictVerifyError::NonCanonicalOrder
    );
    // One manifest twice: one digest, never a conflict.
    assert_eq!(
        verify_err(&frame(&a, &a), &table),
        UpgradeConflictVerifyError::SameDigest
    );
    assert_eq!(
        UpgradeConflictEvidenceV1::from_manifests(&a, &a, &table),
        Err(UpgradeConflictError::Verify(
            UpgradeConflictVerifyError::SameDigest
        ))
    );
    // Two subsets of signers over one body share a digest.
    let mut a_resigned = a.clone();
    a_resigned[MANIFEST_FIXED_LEN + 2] ^= 0x01;
    let subsets = Table(vec![
        (a.clone(), identity(1, "manifest A digest")),
        (a_resigned.clone(), identity(1, "manifest A digest")),
    ]);
    assert_eq!(
        verify_err(&frame(&a, &a_resigned), &subsets),
        UpgradeConflictVerifyError::SameDigest
    );
    // Different sequences.
    let sequences = Table(vec![
        (a.clone(), identity(1, "manifest A digest")),
        (b.clone(), identity(2, "manifest B digest")),
    ]);
    assert_eq!(
        verify_err(&frame(&a, &b), &sequences),
        UpgradeConflictVerifyError::DifferentSequences {
            first: 1,
            second: 2
        }
    );
    // A manifest the verifier refuses, named by its position.
    let only_a = Table(vec![(a.clone(), identity(1, "manifest A digest"))]);
    assert!(matches!(
        verify_err(&frame(&a, &b), &only_a),
        UpgradeConflictVerifyError::ManifestRefused {
            member: Member::Second,
            ..
        }
    ));
    let only_b = Table(vec![(b.clone(), identity(1, "manifest B digest"))]);
    assert!(matches!(
        verify_err(&frame(&a, &b), &only_b),
        UpgradeConflictVerifyError::ManifestRefused {
            member: Member::First,
            ..
        }
    ));
    // A changed manifest byte outside the signer count still frames; only
    // the verifier refuses it.
    let want = draft_conflict();
    for at in [13 + 9, 13 + 200, 13 + MANIFEST_FIXED_LEN + 10] {
        let mut bad = want.clone();
        bad[at] ^= 0x01;
        assert!(UpgradeConflictEvidenceV1::decode(&bad).is_ok());
        assert!(matches!(
            verify_err(&bad, &table),
            UpgradeConflictVerifyError::ManifestRefused {
                member: Member::First,
                ..
            }
        ));
    }
    // Construction checks the framing first.
    assert_eq!(
        UpgradeConflictEvidenceV1::from_manifests(&a[..300], &b, &table),
        Err(UpgradeConflictError::Decode(
            UpgradeConflictDecodeError::ManifestLength {
                member: Member::First,
                actual: 300
            }
        ))
    );
}
